#include <stdio.h>

int main() {
    int t;
    if (scanf("%d", &t) == 1) {
        while (t--) {
            int n;
            scanf("%d", &n);
            int a[n];
            for (int i = 0; i < n; i++) {
                scanf("%d", &a[i]);
            }
            
            // Left-to-right pass
            for (int i = 1; i < n; i++) {
                if (a[i - 1] + 1 < a[i]) {
                    a[i] = a[i - 1] + 1;
                }
            }
            
            // Right-to-left pass
            int i = n - 2;
            while (i >= 0) {
                if (a[i + 1] + 1 < a[i]) {
                    a[i] = a[i + 1] + 1;
                }
                i--;
            }
            
            // Output results
            for (int k = 0; k < n; k++) {
                printf("%d%c", a[k], k == n - 1 ? '\n' : ' ');
            }
        }
    }
    return 0;
}

